\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 1sp. ohne Horiz. in Cursive von mehreren H\u228 \'e4nden geschr.; einige, die eine kleine spitze Schrift f\u252 \'fchren, scheinen \u228 \'e4lter als andere, die sich zugleich einer sehr blassen Tinte bedienen; reichlicher Schmuck in Roth; schwarz verzierte, rothe Initialen; Rubren in Minuskel; Anf\u228 \'e4nge der Abschn. in schwarzer Minuskel, die roth umrahmt ist; Bl. 66 ein Rubr. in Cursive: kaylsterche; Sexter. mit Eckwortcust., Hefte mit Pgt.-Streifen verschiedener Hds. des 14. Jh. beklebt. Wz.: 2 Kreise mit Stern an einer Achse, Ochsenkopf ohne Beizeichen u. Ochsenkopf mit Stern.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;}

