\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f0\fs16 (Schum:) Bl. 15'--17' u. 88' -- 92'. Eiusdem arithmetica. (Nicht im Cat.) Rubr.: Inc. arism. eiusdem. Anf.: (H)orum que sunt aliud est continuum, aliud discretum. Ende: hec est sesquioctava proportio differencia. Expl. arism. Bragward.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f0\fs16 (Schum:) Bl. 18--84'. Sex libri elementorum Euclidis cum commento Campani et figuris. Anf.: Primus liber Euclidis. Punctus est cuius pars non est. Linea est. Ende: quod intellige in eodem circulo. Et sic est finis sexti libri geometrie Eucl. Inc. septimus lib. Eucl.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f0\fs16 (Schum:) Bl. 85--88 u. 93--112'. Textus duarum dictionum Almagesti Ptholomei. Anf.: Principium Almagesti breviato cum commento. Data circuli dyametro, latera decagoni --. Summa vero principiorum. Ende: duobus angulis rectis. Illud est, quod declarare nos oportuit.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;}

